import { forwardRef, useEffect, useImperativeHandle, useRef } from "react";
import { Alignment, Fit, Layout, Rive, RuntimeLoader, type StateMachineInput } from "@rive-app/canvas";
import riveWasmUrl from "@rive-app/canvas/rive.wasm?url";
// Generated by packages/axo-mascot; see its README for the artboards and inputs.
import mascotUrl from "../../../assets/mascot/axo.riv?url";

// The runtime would otherwise fetch its wasm from a CDN.
RuntimeLoader.setWasmUrl(riveWasmUrl);

/** Names in `packages/axo-mascot/src/mascot.ts` (`MascotContract`). */
const Contract = {
  artboard: "Face",
  stateMachine: "Mascot",
  poke: "poke",
  annoyed: "annoyed",
  tracking: "tracking",
  covering: "covering",
  lookX: "lookX",
  lookY: "lookY",
} as const;

/** The `Face` artboard is 1064 x 604 (`MascotBounds.face` in packages/axo-mascot). */
const ASPECT_RATIO = 1064 / 604;
/** After the pointer stops moving for this long, Axo goes back to looking around on its own. */
const LOOK_AWAY_AFTER_MS = 1600;

export type AxoMascotHandle = {
  /** Hands over the eyes, or down again. */
  cover(covering: boolean): void;
};

/**
 * Pokes less than `streakGapMs` apart form a streak: the first pokes giggle, the fourth annoys
 * Axo, and while it is annoyed more pokes do nothing (the phone's `MascotPokes`, in TypeScript).
 */
export class MascotPokes {
  static readonly streakGapMs = 700;
  static readonly annoyedAt = 4;
  static readonly annoyedForMs = 1200;
  private streak = 0;
  private lastPoke: number | null = null;
  private annoyedUntil: number | null = null;

  poke(now: number): "giggle" | "annoyed" | null {
    if (this.annoyedUntil !== null && now < this.annoyedUntil) return null;
    this.annoyedUntil = null;
    this.streak = this.lastPoke !== null && now - this.lastPoke <= MascotPokes.streakGapMs ? this.streak + 1 : 1;
    this.lastPoke = now;
    if (this.streak < MascotPokes.annoyedAt) return "giggle";
    this.streak = 0;
    this.lastPoke = null;
    this.annoyedUntil = now + MascotPokes.annoyedForMs;
    return "annoyed";
  }
}

/** The blinking Axo axolotl. It watches the pointer, and giggles (or gets annoyed) when poked. */
export const AxoMascot = forwardRef<AxoMascotHandle, { className?: string }>(function AxoMascot({ className }, ref) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const riveRef = useRef<Rive | null>(null);
  const inputs = (name: string): StateMachineInput | undefined =>
    riveRef.current?.stateMachineInputs(Contract.stateMachine)?.find((input) => input.name === name);

  useImperativeHandle(ref, () => ({
    cover(covering) {
      const input = inputs(Contract.covering);
      if (input) input.value = covering;
    },
  }), []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rive = new Rive({
      src: mascotUrl,
      canvas,
      artboard: Contract.artboard,
      stateMachines: Contract.stateMachine,
      autoplay: !reduceMotion,
      layout: new Layout({ fit: Fit.Contain, alignment: Alignment.Center }),
      onLoad: () => rive.resizeDrawingSurfaceToCanvas(),
    });
    riveRef.current = rive;
    const resize = () => rive.resizeDrawingSurfaceToCanvas();
    window.addEventListener("resize", resize);

    // Look from the mascot's centre towards the pointer; half the window away is all the way.
    let lookAway: number | undefined;
    const look = (event: PointerEvent) => {
      if (event.pointerType !== "mouse" && event.buttons === 0) return;
      const box = canvas.getBoundingClientRect();
      const clamp = (value: number) => Math.max(-100, Math.min(100, value));
      const lookX = inputs(Contract.lookX);
      const lookY = inputs(Contract.lookY);
      const tracking = inputs(Contract.tracking);
      if (!lookX || !lookY || !tracking) return;
      lookX.value = clamp(((event.clientX - (box.left + box.width / 2)) / (window.innerWidth / 2)) * 100);
      lookY.value = clamp(((event.clientY - (box.top + box.height / 2)) / (window.innerHeight / 2)) * 100);
      tracking.value = true;
      window.clearTimeout(lookAway);
      lookAway = window.setTimeout(stopLooking, LOOK_AWAY_AFTER_MS);
    };
    const stopLooking = () => {
      const tracking = inputs(Contract.tracking);
      if (tracking) tracking.value = false;
    };
    const touchEnded = (event: PointerEvent) => {
      if (event.pointerType !== "mouse") stopLooking();
    };
    window.addEventListener("pointermove", look);
    window.addEventListener("pointerdown", look);
    window.addEventListener("pointerup", touchEnded);
    window.addEventListener("pointercancel", touchEnded);
    document.documentElement.addEventListener("pointerleave", stopLooking);

    return () => {
      window.clearTimeout(lookAway);
      window.removeEventListener("resize", resize);
      window.removeEventListener("pointermove", look);
      window.removeEventListener("pointerdown", look);
      window.removeEventListener("pointerup", touchEnded);
      window.removeEventListener("pointercancel", touchEnded);
      document.documentElement.removeEventListener("pointerleave", stopLooking);
      riveRef.current = null;
      rive.cleanup();
    };
  }, []);

  const pokes = useRef(new MascotPokes());
  const poke = () => {
    const reaction = pokes.current.poke(performance.now());
    if (reaction) inputs(reaction === "giggle" ? Contract.poke : Contract.annoyed)?.fire();
  };

  return (
    <canvas
      ref={canvasRef}
      className={className}
      style={{ aspectRatio: String(ASPECT_RATIO) }}
      role="img"
      aria-label="Axo"
      onClick={poke}
    />
  );
});
